pub type AppError = Failed(String)

pub record Sample { n: Int64 }

pub interface Classifier {
    fn score(self, x: Sample) -> Int64
}

impl Classifier for Sample {
    fn score(self, x: Sample) -> Int64 {
        if x.n > 10 {
            return 2
        }
        return 1
    }
}

pub fn main() -> Result<(), AppError> {
    return Ok(())
}

